"use client";

import React, { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";

type Props = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (password: string) => Promise<void> | void;
};

export default function PasswordDialog({
  open,
  onOpenChange,
  onSubmit,
}: Props) {
  const [password, setPassword] = useState("");

  // 🟢 Clear password every time modal opens
  useEffect(() => {
    if (open) {
      setPassword("");
    }
  }, [open]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-sm p-6 rounded-xl shadow-lg">
        <DialogHeader>
          <DialogTitle className="text-center">Enter Password</DialogTitle>
          <DialogDescription className="text-center mt-1">
            To access wage management please confirm your login password.
          </DialogDescription>
        </DialogHeader>

        <form
          onSubmit={(e) => {
            e.preventDefault();
            onSubmit(password);
          }}
          className="flex gap-2 mt-4"
        >
          <Input
            type="password"
            placeholder="Your password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="flex-1"
            autoFocus
          />
          <Button type="submit">Enter</Button>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import React, { useState, useEffect, useMemo } from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { Checkbox } from "@/components/ui/checkbox";
import { 
  Search, 
  Plus, 
  Edit, 
  Trash2, 
  RefreshCw, 
  Calendar, 
  Layers, 
  PhilippinePeso, 
  Info,
  ShieldCheck,
  TrendingUp,
  Activity, 
  Award, 
  Wallet, 
  Clock,
  AlertTriangle,
  RotateCcw
} from "lucide-react";
import { toast } from "sonner";
import * as wageApi from "../providers/wageApi";
import type { SalarySchedule, SalarySchedulePayload } from "../types";

export function SalaryGradeManagement() {
  const [schedules, setSchedules] = useState<SalarySchedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [refreshKey, setRefreshKey] = useState(0);

  // Modal state
  const [modalOpen, setModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [formData, setFormData] = useState<SalarySchedulePayload>({
    effectivity_date: new Date().toISOString().split("T")[0],
    salary_grade: 1,
    step: 1,
    monthly_rate: 0,
  });
  const [rateDisplay, setRateDisplay] = useState("");

  // Warning Prompt state
  const [warningPromptOpen, setWarningPromptOpen] = useState(false);
  const [dontAskAgain, setDontAskAgain] = useState(false);
  const [pendingEdit, setPendingEdit] = useState<SalarySchedule | null>(null);


  useEffect(() => {
    loadSchedules();
  }, [refreshKey]);

  const loadSchedules = async () => {
    setLoading(true);
    try {
      const data = await wageApi.fetchSalarySchedules();
      setSchedules(data);
    } catch (err) {
      console.error(err);
      toast.error("Failed to load salary schedules.");
    } finally {
      setLoading(false);
    }
  };

  const handleRefresh = () => setRefreshKey((prev) => prev + 1);

  const filteredSchedules = useMemo(() => {
    if (!searchTerm) return schedules;
    const s = searchTerm.toLowerCase();
    return schedules.filter(
      (sch) =>
        sch.salary_grade.toString().includes(s) ||
        sch.effectivity_date.includes(s) ||
        sch.monthly_rate.toString().includes(s)
    );
  }, [schedules, searchTerm]);

  // Pagination logic
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm]);

  const totalPages = Math.ceil(filteredSchedules.length / rowsPerPage) || 1;
  const paginatedSchedules = useMemo(() => {
    const start = (currentPage - 1) * rowsPerPage;
    return filteredSchedules.slice(start, start + rowsPerPage);
  }, [filteredSchedules, currentPage, rowsPerPage]);

  const handleOpenAdd = () => {
    setEditingId(null);
    setFormData({
      effectivity_date: new Date().toISOString().split("T")[0],
      salary_grade: 1,
      step: 1,
      monthly_rate: 0,
    });
    setRateDisplay("");
    setModalOpen(true);
  };

  const handleOpenEdit = (sch: SalarySchedule) => {
    // Check if user has previously dismissed the warning
    const isDismissed = localStorage.getItem("sg_edit_warning_dismissed") === "true";

    if (isDismissed) {
      executeOpenEdit(sch);
    } else {
      setPendingEdit(sch);
      setWarningPromptOpen(true);
    }
  };

  const executeOpenEdit = (sch: SalarySchedule) => {
    setEditingId(sch.schedule_id);
    setFormData({
      effectivity_date: sch.effectivity_date,
      salary_grade: sch.salary_grade,
      step: sch.step,
      monthly_rate: Number(sch.monthly_rate),
    });
    // Initialize formatted value
    const parts = Number(sch.monthly_rate).toString().split(".");
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    setRateDisplay(parts.join("."));
    setModalOpen(true);
  };

  const handleConfirmWarning = () => {
    if (dontAskAgain) {
      localStorage.setItem("sg_edit_warning_dismissed", "true");
    }
    if (pendingEdit) {
      executeOpenEdit(pendingEdit);
    }
    setWarningPromptOpen(false);
  };

  const handleResetWarnings = () => {
    localStorage.removeItem("sg_edit_warning_dismissed");
    setDontAskAgain(false);
    toast.success("Notice settings reset. Update warnings will now reappear.");
  };


  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingId) {
        await wageApi.patchSalarySchedule(editingId, formData);
        toast.success("Schedule updated successfully.");
      } else {
        await wageApi.createSalarySchedule(formData);
        toast.success("Schedule created successfully.");
      }
      setModalOpen(false);
      handleRefresh();
    } catch (err) {
      console.error(err);
      toast.error("Failed to save schedule.");
    }
  };

  const handleRateInput = (val: string) => {
    const rawValue = val.replace(/,/g, "");
    // Allow only numbers and a single decimal point
    if (/^\d*\.?\d*$/.test(rawValue)) {
      const parts = rawValue.split(".");
      // Limit decimal digits to 2
      if (parts[1] && parts[1].length > 2) return;

      parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",");
      setRateDisplay(parts.join("."));
      setFormData({ ...formData, monthly_rate: Number(rawValue) });
    }
  };

  // Metrics calculation
  const stats = useMemo(() => ({
    total: filteredSchedules.length,
    activeGrades: new Set(filteredSchedules.map(s => s.salary_grade)).size,
    latestMonthly: Math.max(...schedules.map(s => Number(s.monthly_rate)), 0),
    avgMonthly: schedules.length > 0
      ? schedules.reduce((acc, s) => acc + Number(s.monthly_rate), 0) / schedules.length
      : 0
  }), [schedules, filteredSchedules]);

  const getStatus = (date: string) => {
    const effDate = new Date(date);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    return effDate <= today ? "Active" : "Upcoming";
  };

  return (
    <div className="space-y-6 font-sans">
      {/* Stats Summary Section */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mt-2">
        <div className="bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 p-4 rounded-xl shadow-sm flex items-center gap-4 transition-all hover:shadow-md hover:border-blue-100/50">
          <div className="h-10 w-10 bg-blue-50 dark:bg-blue-900/10 text-blue-600 rounded-lg flex items-center justify-center">
            <Activity className="h-5 w-5" />
          </div>
          <div>
            <p className="text-[10px] font-bold uppercase text-gray-400 dark:text-gray-500 tracking-wider">Total Records</p>
            <p className="text-xl font-bold text-gray-900 dark:text-gray-100">{stats.total}</p>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 p-4 rounded-xl shadow-sm flex items-center gap-4 transition-all hover:shadow-md hover:border-blue-100/50">
          <div className="h-10 w-10 bg-emerald-50 dark:bg-emerald-900/10 text-emerald-600 rounded-lg flex items-center justify-center">
            <Award className="h-5 w-5" />
          </div>
          <div>
            <p className="text-[10px] font-bold uppercase text-gray-400 dark:text-gray-500 tracking-wider">Active Grades</p>
            <p className="text-xl font-bold text-gray-900 dark:text-gray-100">{stats.activeGrades}</p>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 p-4 rounded-xl shadow-sm flex items-center gap-4 transition-all hover:shadow-md hover:border-blue-100/50">
          <div className="h-10 w-10 bg-amber-50 dark:bg-amber-900/10 text-amber-600 rounded-lg flex items-center justify-center">
            <Wallet className="h-5 w-5" />
          </div>
          <div>
            <p className="text-[10px] font-bold uppercase text-gray-400 dark:text-gray-500 tracking-wider">Ceiling Rate</p>
            <p className="text-xl font-bold text-gray-900 dark:text-gray-100">
              {stats.latestMonthly.toLocaleString()}
            </p>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-900 border border-gray-100 dark:border-gray-800 p-4 rounded-xl shadow-sm flex items-center gap-4 transition-all hover:shadow-md hover:border-blue-100/50">
          <div className="h-10 w-10 bg-indigo-50 dark:bg-indigo-900/10 text-indigo-600 rounded-lg flex items-center justify-center">
            <TrendingUp className="h-5 w-5" />
          </div>
          <div>
            <p className="text-[10px] font-bold uppercase text-gray-400 dark:text-gray-500 tracking-wider">Avg. Monthly</p>
            <p className="text-xl font-bold text-gray-900 dark:text-gray-100">
              {stats.avgMonthly.toLocaleString(undefined, { maximumFractionDigits: 0 })}
            </p>
          </div>
        </div>
      </div>

      <Separator className="my-2" />

      {/* Toolbar */}
      <div className="flex flex-col md:flex-row gap-4 items-end justify-between">
        {/* Left Side: Search */}
        <div className="flex-1 w-full md:max-w-md space-y-1">
          <label className="text-xs font-medium text-gray-500">Search schedule</label>
          <div className="relative">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Search by grade, date, or rate..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-9 h-10 shadow-sm"
            />
          </div>
        </div>

        {/* Right Side: Actions */}
        <div className="flex flex-wrap gap-2 w-full md:w-auto">
          <div className="space-y-1 w-full md:w-auto">
            <label className="text-xs font-medium text-gray-500">Quick Actions</label>
            <div className="flex gap-2">
              <Button
                variant="outline"
                className="h-10 px-3 gap-2 text-gray-500 border-gray-200 hover:text-blue-600 shadow-none bg-transparent"
                onClick={handleResetWarnings}
                title="Reset Notice Preferences"
              >
                <RotateCcw className="h-4 w-4" />
              </Button>
              <Button
                variant="outline"
                className="h-10 px-3 gap-2 text-gray-600 border-gray-300 shadow-sm"
                onClick={handleRefresh}
                title="Refresh Records"
              >
                <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
                <span className="hidden lg:inline">Refresh</span>
              </Button>
              <Button 
                onClick={handleOpenAdd} 
                className="h-10 px-4 gap-2 bg-blue-600 hover:bg-blue-700 text-white shadow-sm font-medium"
              >
                <Plus className="h-4 w-4" />
                Add Schedule
              </Button>
            </div>
          </div>
        </div>
      </div>

      <Separator className="my-4" />

      {/* Table */}
      <div className="border rounded-md overflow-hidden">
        <Table>
          <TableHeader className="bg-gray-50 dark:bg-gray-800">
            <TableRow>
              <TableHead className="text-gray-600 font-semibold py-3 px-4 text-xs">Effectivity Date</TableHead>
              <TableHead className="text-gray-600 font-semibold py-3 px-4 text-xs text-center">Status</TableHead>
              <TableHead className="text-gray-600 font-semibold py-3 px-4 text-xs text-center">Salary Grade</TableHead>
              <TableHead className="text-gray-600 font-semibold py-3 px-4 text-xs text-center">Step Level</TableHead>
              <TableHead className="text-gray-600 font-semibold py-3 px-4 text-xs">Monthly Rate</TableHead>
              <TableHead className="text-gray-600 font-semibold py-3 px-4 text-xs">Annual Gross</TableHead>
              <TableHead className="text-right text-gray-600 font-semibold py-3 px-4 text-xs">Actions</TableHead>
            </TableRow>
          </TableHeader>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={5} className="h-40 text-center text-gray-400">
                    <div className="flex flex-col items-center gap-3">
                      <div className="h-10 w-10 border-4 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
                      <span className="text-sm font-semibold tracking-wide uppercase">Fetching Records</span>
                    </div>
                  </TableCell>
                </TableRow>
              ) : filteredSchedules.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={5} className="h-40 font-medium text-center text-gray-400">
                    No active salary schedules found.
                  </TableCell>
                </TableRow>
              ) : (
                paginatedSchedules.map((sch) => (
                  <TableRow key={sch.schedule_id} className="hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors">
                    <TableCell className="px-4 py-3 font-medium text-gray-500 text-sm whitespace-nowrap">
                      {sch.effectivity_date}
                    </TableCell>
                    <TableCell className="px-4 py-3 text-center">
                      {getStatus(sch.effectivity_date) === "Active" ? (
                        <span className="inline-flex items-center px-2 py-0.5 bg-emerald-50 dark:bg-emerald-950/30 text-emerald-700 dark:text-emerald-400 rounded-full text-[10px] font-bold border border-emerald-100 dark:border-emerald-900/50">
                          Active
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-2 py-0.5 bg-blue-50 dark:bg-blue-950/30 text-blue-700 dark:text-blue-400 rounded-full text-[10px] font-bold border border-blue-100 dark:border-blue-900/50">
                          Upcoming
                        </span>
                      )}
                    </TableCell>
                    <TableCell className="px-4 py-3 text-center">
                      <span className="inline-flex items-center px-2 py-0.5 bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-md text-xs font-semibold border border-gray-200 dark:border-gray-700/50 shadow-sm">
                        SG {sch.salary_grade}
                      </span>
                    </TableCell>
                    <TableCell className="px-4 py-3 text-center text-gray-600 dark:text-gray-300 text-sm">Step {sch.step}</TableCell>
                    <TableCell className="px-4 py-3 font-medium text-gray-900 dark:text-gray-100 text-sm tabular-nums">
                      {Number(sch.monthly_rate).toLocaleString(undefined, {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 2
                      })}
                    </TableCell>
                    <TableCell className="px-4 py-3 font-medium text-gray-500 dark:text-gray-400 text-sm tabular-nums">
                      {(Number(sch.monthly_rate) * 12).toLocaleString(undefined, {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 2
                      })}
                    </TableCell>
                    <TableCell className="px-4 py-3 text-right">
                      <div className="flex justify-end gap-1.5">
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-8 w-8 p-0 text-blue-600 border-blue-200 hover:bg-blue-50 hover:text-blue-700 rounded-md"
                          onClick={() => handleOpenEdit(sch)}
                          title="Edit Schedule"
                        >
                          <Edit size={14} />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>

      {/* Pagination Controls */}
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-4 border-t border-gray-50 dark:border-gray-900 mt-2">
        <div className="flex items-center gap-4">
          <div className="text-sm text-gray-500">
            Showing{" "}
            {filteredSchedules.length > 0 ? (currentPage - 1) * rowsPerPage + 1 : 0} to{" "}
            {Math.min(currentPage * rowsPerPage, filteredSchedules.length)} of{" "}
            {filteredSchedules.length} entries
          </div>

          <div className="hidden sm:flex items-center gap-2 border-l pl-4">
            <span className="text-[10px] font-bold uppercase text-gray-400">Rows:</span>
            <Select
              value={String(rowsPerPage)}
              onValueChange={(v) => {
                setRowsPerPage(Number(v));
                setCurrentPage(1);
              }}
            >
              <SelectTrigger className="h-7 w-[70px] text-xs font-semibold bg-transparent border-none shadow-none focus:ring-0">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="min-w-[70px]">
                <SelectItem value="5">5</SelectItem>
                <SelectItem value="10">10</SelectItem>
                <SelectItem value="20">20</SelectItem>
                <SelectItem value="50">50</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
            disabled={currentPage === 1}
            className="h-8 px-3 text-gray-600 border-gray-200 hover:bg-gray-50"
          >
            Prev
          </Button>
          <div className="flex items-center gap-1 mx-2">
            <span className="text-xs text-gray-400">Page</span>
            <span className="text-xs font-bold text-gray-900 dark:text-gray-100">{currentPage}</span>
            <span className="text-xs text-gray-400">of</span>
            <span className="text-xs font-bold text-gray-900 dark:text-gray-100">{totalPages}</span>
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
            disabled={currentPage === totalPages || totalPages === 0}
            className="h-8 px-3 text-gray-600 border-gray-200 hover:bg-gray-50"
          >
            Next
          </Button>
        </div>
      </div>

      {/* Add/Edit Modal */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent className="sm:max-w-[460px] p-0 overflow-hidden border-none shadow-3xl rounded-3xl bg-white dark:bg-gray-950 max-h-[85vh] flex flex-col">
          <form onSubmit={handleSubmit} className="flex flex-col h-full overflow-hidden">

            {/* COMPACT HEADER */}
            <div className="px-6 pt-6 pb-3 shrink-0 border-b border-gray-50 dark:border-gray-900">
              <DialogHeader className="space-y-3 text-left">
                <div className="flex items-center gap-3">
                  <div className="h-10 w-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/10 ring-4 ring-blue-500/5">
                    <ShieldCheck size={20} className="text-white fill-blue-400/20" />
                  </div>
                  <div className="space-y-0.5">
                    <DialogTitle className="text-xl font-bold text-gray-900 dark:text-gray-100 tracking-tight">
                      {editingId ? "Update Schedule" : "Add New Schedule"}
                    </DialogTitle>
                    <div className="text-[10px] font-bold text-blue-600 uppercase tracking-widest flex items-center gap-1.5 mt-0.5">
                      <div className="h-1 w-1 bg-blue-600 rounded-full animate-pulse"></div>
                      Compensation Management Unit
                    </div>
                  </div>
                </div>
                <DialogDescription className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed font-medium">
                  Define standardized monthly rates for specific grades and steps. This data synchronizes across all automated systems.
                </DialogDescription>
              </DialogHeader>
            </div>

            {/* SCROLLABLE BODY */}
            <div className="p-6 space-y-4 overflow-y-auto max-h-[calc(85vh-160px)] custom-scrollbar">

              {/* EFFECTIVITY */}
              <div className="space-y-2">
                <Label htmlFor="effectivity" className="text-[10px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-[0.12em] ml-1 flex items-center gap-2">
                  <Calendar size={12} className="text-gray-400" />
                  Effective Start Date
                </Label>
                <div className="relative group">
                  <Input
                    id="effectivity"
                    type="date"
                    value={formData.effectivity_date}
                    onChange={(e) =>
                      setFormData({ ...formData, effectivity_date: e.target.value })
                    }
                    className="h-10 bg-gray-50/50 dark:bg-gray-900/30 border-gray-100 dark:border-gray-800 rounded-xl focus:ring-[6px] focus:ring-blue-500/5 focus:border-blue-500/50 transition-all pl-10 font-semibold text-sm tracking-tight"
                    required
                  />
                  <Calendar className="absolute left-3.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-gray-400 group-focus-within:text-blue-600 transition-colors" />
                </div>
              </div>

              {/* GRADE & STEP GRID */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="grade" className="text-[10px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-[0.12em] ml-1 flex items-center gap-2">
                    <Layers size={11} className="text-gray-400" />
                    Salary Grade
                  </Label>
                  <Select
                    value={String(formData.salary_grade)}
                    onValueChange={(v) =>
                      setFormData({ ...formData, salary_grade: Number(v) })
                    }
                  >
                    <SelectTrigger className="h-10 bg-gray-50/50 dark:bg-gray-900/30 border-gray-100 dark:border-gray-800 rounded-xl focus:ring-4 focus:ring-blue-500/5 font-semibold transition-all">
                      <SelectValue placeholder="SG" />
                    </SelectTrigger>
                    <SelectContent className="rounded-2xl border-gray-100 dark:border-gray-800">
                      {Array.from({ length: 33 }, (_, i) => i + 1).map((g) => (
                        <SelectItem key={g} value={String(g)} className="font-bold text-xs py-2.5">
                          SG {g}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="step" className="text-[10px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-[0.12em] ml-1 flex items-center gap-2">
                    <TrendingUp size={11} className="text-gray-400" />
                    Step Level
                  </Label>
                  <Select
                    value={String(formData.step)}
                    onValueChange={(v) =>
                      setFormData({ ...formData, step: Number(v) })
                    }
                  >
                    <SelectTrigger className="h-10 bg-gray-50/50 dark:bg-gray-900/30 border-gray-100 dark:border-gray-800 rounded-xl focus:ring-4 focus:ring-blue-500/5 font-semibold transition-all">
                      <SelectValue placeholder="Step" />
                    </SelectTrigger>
                    <SelectContent className="rounded-2xl border-gray-100 dark:border-gray-800">
                      {Array.from({ length: 8 }, (_, i) => i + 1).map((s) => (
                        <SelectItem key={s} value={String(s)} className="font-semibold text-xs py-2.5">
                          Step {s}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>

              {/* MONTHLY RATE */}
              <div className="space-y-2">
                <Label htmlFor="rate" className="text-[10px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-[0.12em] ml-1 flex items-center gap-2">
                  <PhilippinePeso size={11} className="text-gray-400" />
                  Monthly Basic Salary
                </Label>
                <div className="relative group">
                  <Input
                    id="rate"
                    type="text"
                    placeholder="e.g. 21,500.00"
                    value={rateDisplay}
                    onChange={(e) => handleRateInput(e.target.value)}
                    className="h-12 bg-gray-50/50 dark:bg-gray-900/30 border-gray-100 dark:border-gray-800 rounded-xl focus:ring-[6px] focus:ring-blue-500/5 focus:border-blue-500/50 transition-all pl-11 font-mono text-lg font-bold text-gray-900 dark:text-gray-100 placeholder:font-sans placeholder:text-xs placeholder:font-semibold placeholder:text-gray-400"
                    required
                  />
                  <PhilippinePeso className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4.5 w-4.5 text-gray-400 group-focus-within:text-blue-600 transition-colors stroke-[2]" />
                </div>
              </div>

              {/* COMPACT INFO BOX */}
              <div className="bg-blue-50/30 dark:bg-blue-900/10 border border-blue-100/30 dark:border-blue-500/10 p-3.5 rounded-xl flex gap-3 relative overflow-hidden group/info">
                <div className="shrink-0 h-8 w-8 bg-white dark:bg-gray-900 rounded-lg border border-blue-100/50 dark:border-blue-800/20 flex items-center justify-center shadow-sm">
                  <Info size={14} className="text-blue-600" />
                </div>
                <div className="space-y-1 relative z-10">
                  <h5 className="text-[10px] font-bold uppercase text-blue-700 dark:text-blue-400 tracking-wide">Sync Assurance</h5>
                  <p className="text-[10px] leading-relaxed text-gray-600 dark:text-gray-400 font-semibold italic opacity-80 decoration-blue-500/20 underline underline-offset-4 line-clamp-2">
                    Ensure rates comply with organizational standards before submission. System auto-verifies baseline logic.
                  </p>
                </div>
              </div>
            </div>

            {/* STICKY FOOTER */}
            <DialogFooter className="p-6 border-t border-gray-50 dark:border-gray-900 bg-gray-50/20 flex flex-col-reverse sm:flex-row gap-2 shrink-0">
              <Button 
                type="button" 
                variant="ghost" 
                onClick={() => setModalOpen(false)} 
                className="w-full sm:w-auto h-10 px-4 rounded-xl text-gray-400 font-bold text-[10px] uppercase tracking-widest hover:bg-white dark:hover:bg-gray-900 hover:text-red-500 transition-all"
              >
                Cancel
              </Button>
              <Button 
                type="submit" 
                className="w-full sm:flex-1 h-10 bg-gray-900 dark:bg-blue-600 hover:bg-black dark:hover:bg-blue-700 text-white font-bold text-[10px] uppercase tracking-[0.2em] rounded-xl shadow-xl shadow-blue-500/10 active:scale-[0.97] transition-all"
              >
                {editingId ? "Finalize Update" : "Save Changes"}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
      {/* --- WARNING PROMPT DIALOG --- */}
      <Dialog open={warningPromptOpen} onOpenChange={setWarningPromptOpen}>
        <DialogContent className="sm:max-w-[420px] p-0 overflow-hidden border-none shadow-2xl rounded-3xl bg-white dark:bg-gray-950">
          <div className="p-8 space-y-7">
            <div className="flex flex-col items-center text-center space-y-5">
              <div className="h-20 w-20 bg-amber-100/50 dark:bg-amber-900/30 rounded-3xl flex items-center justify-center shadow-inner shadow-white/20 ring-8 ring-amber-500/10 transition-transform hover:scale-105 duration-500">
                <AlertTriangle size={40} className="text-amber-600 drop-shadow-sm" />
              </div>
              <DialogHeader className="space-y-3">
                <DialogTitle className="text-2xl font-black text-gray-900 dark:text-gray-100 tracking-tight text-center">
                  Data Persistence Notice
                </DialogTitle>
                <DialogDescription className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed text-center font-medium max-w-[280px] mx-auto">
                  Only update the schedule to fix <span className="text-amber-700 dark:text-amber-500 font-bold underline decoration-amber-500/30 underline-offset-4">informational errors</span>.
                </DialogDescription>
              </DialogHeader>
            </div>

            <div className="bg-amber-50/50 dark:bg-amber-900/10 p-5 rounded-2xl border border-amber-100 dark:border-amber-500/10 space-y-4 shadow-sm">
              <p className="text-xs text-gray-700 dark:text-gray-300 font-semibold leading-relaxed text-center">
                If this is a <span className="text-blue-600 dark:text-blue-400 font-extrabold underline decoration-blue-500/20 underline-offset-4">rate adjustment</span>, please create a new schedule to preserve history.
              </p>

              <div className="flex items-center justify-center space-x-3 pt-3 border-t border-amber-100/50 dark:border-amber-500/10">
                <Checkbox 
                  id="dontAsk" 
                  checked={dontAskAgain} 
                  onCheckedChange={(checked) => setDontAskAgain(checked as boolean)}
                  className="rounded-md border-amber-300 dark:border-amber-700 data-[state=checked]:bg-amber-600 data-[state=checked]:border-amber-600 h-4.5 w-4.5" 
                />
                <label 
                  htmlFor="dontAsk" 
                  className="text-[10px] font-black text-amber-800 dark:text-amber-500 uppercase tracking-widest cursor-pointer select-none"
                >
                  Don't show this again
                </label>
              </div>
            </div>

            <div className="flex flex-col gap-3 pt-2">
              <Button 
                onClick={handleConfirmWarning}
                className="w-full h-12 bg-gray-900 dark:bg-amber-600 hover:bg-black dark:hover:bg-amber-700 text-white font-bold text-xs uppercase tracking-[0.2em] rounded-2xl shadow-xl shadow-amber-950/20 transition-all active:scale-[0.98]"
              >
                Proceed to Update
              </Button>
              <Button 
                variant="ghost" 
                onClick={() => setWarningPromptOpen(false)}
                className="w-full h-12 rounded-2xl text-gray-500 font-bold text-xs uppercase tracking-widest hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-950/20 transition-all"
              >
                Go Back
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

    </div>
  );
}

// modules/wage/components/WageModal.tsx
"use client";

import React from "react";
import { toast } from "sonner";

import { WageTab } from "./tabs/WageTab";
import { LoansTab } from "./tabs/LoansTab";
import { RetroPayTab } from "./tabs/RetroPayTab";
import { AllowanceTab } from "./tabs/AllowanceTab";
import { BenefitsTab } from "./tabs/BenefitsTab";
import { OtherADTab } from "./tabs/OtherADTab";
import { StockPurchaseTab } from "./tabs/StockPurchaseTab";
import { SavingsTab } from "./tabs/SavingsTab";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";

import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";

import {
  X,
  Wallet,
  HandCoins,
  History,
  BadgeDollarSign,
  ShieldCheck,
  Layers,
  ReceiptText,
  PiggyBank,
} from "lucide-react";

import type {
  Employee,
  WageDataState,
  EmployeeLoanRecord,
  LoanType,
  RetroPayRecord,
  RetroPayDraft,
  CutoffSetting,
  PayrollOtherAdditionRecord,
  PayrollOtherDeductionRecord,
  PayrollOtherADDraft,
  SalarySchedule,
} from "../types";

import * as wageApi from "../providers/wageApi";

import {
  toLocalYmd,
  round2,
  money,
  computeMonthlyPayment,
  computeCoopInterest,
} from "../utils/loanMath";

type Props = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  selectedEmployee: Employee | null;
  wageData: WageDataState;
  setWageData: (upd: Partial<WageDataState>) => void;
  onSave: () => Promise<void> | void;
  salarySchedules: SalarySchedule[];
};

type LoanDraft = {
  loan_amount: string;
  loan_type: LoanType;
  months_to_pay: string;
  start_date: string;
  end_date: string;

  monthly_payment: string; // auto
  interest_rate: string; // auto for COOP, else 0
  interest_amount: string; // auto for COOP, else 0
  net_amount_released: string; // auto for COOP, else 0

  accumulated_amount: string;

  status: string;
};

function isYmd(s: string) {
  return /^\d{4}-\d{2}-\d{2}$/.test(s);
}

function getLoggedUserId(): number | null {
  const session = sessionStorage.getItem("user");
  if (!session) return null;
  try {
    const logged = JSON.parse(session);
    const n = Number(logged?.user_id);
    return Number.isFinite(n) ? n : null;
  } catch {
    return null;
  }
}

const TAB_KEYS = [
  "wage",
  "savings",
  "loans",
  "retro",
  "allowance",
  "benefits",
  "stock",
  "other",
] as const;

type TabKey = (typeof TAB_KEYS)[number];

export default function WageModal({
  open,
  onOpenChange,
  selectedEmployee,
  wageData,
  setWageData,
  onSave,
  salarySchedules,
}: Props) {
  // ✅ Modal width (wider to reduce table pressure)
  const MODAL_WIDTH = "max-w-[96vw] sm:max-w-6xl lg:max-w-7xl";

  // ✅ Table-fit scope:
  // - Prevent internal wrappers from creating horizontal scrollbars
  // - Force tables to fit the container
  // - Slightly tighten typography/padding for dense tables
  const TABLE_FIT_SCOPE =
    "overflow-x-hidden " +
    "[&_.overflow-auto]:overflow-x-hidden [&_.overflow-auto]:overflow-y-auto " +
    "[&_.overflow-x-auto]:overflow-x-hidden [&_.overflow-x-auto]:overflow-y-auto " +
    "[&_[data-radix-scroll-area-viewport]]:overflow-x-hidden " +
    "[&_table]:w-full [&_table]:table-fixed [&_table]:min-w-0 " +
    "[&_th]:whitespace-nowrap [&_th]:p-2 [&_td]:p-2 " +
    "[&_th]:text-[12px] sm:[&_th]:text-sm [&_td]:text-[12px] sm:[&_td]:text-sm " +
    // allow content to wrap instead of expanding width
    "[&_td]:whitespace-normal [&_td]:break-words";

  // Theme tokens
  const PAYROLL_PRIMARY =
    "bg-persian-blue-800 hover:bg-persian-blue-700 text-white";
  const PAYROLL_OUTLINE =
    "border border-slate-200 bg-white text-slate-700 hover:bg-slate-50 hover:text-slate-900 " +
    "dark:bg-transparent dark:text-slate-200 dark:border-slate-700 dark:hover:bg-slate-900/40";
  const PAYROLL_ICON_BTN =
    "h-9 w-9 p-0 border border-slate-200 bg-white hover:bg-slate-50 " +
    "dark:bg-transparent dark:border-slate-700 dark:hover:bg-slate-900/40";
  const PAYROLL_ICON_EDIT = "text-persian-blue-800 hover:text-persian-blue-700";
  const PAYROLL_ICON_DELETE = "text-red-600 hover:text-red-700";

  const ui = React.useMemo(
    () => ({
      primary: PAYROLL_PRIMARY,
      outline: PAYROLL_OUTLINE,
      iconBtn: PAYROLL_ICON_BTN,
      iconEdit: PAYROLL_ICON_EDIT,
      iconDelete: PAYROLL_ICON_DELETE,
    }),
    [],
  );

  // Tabs (✅ include savings)
  const [tab, setTab] = React.useState<TabKey>("wage");

  React.useEffect(() => {
    if (open) setTab("wage");
  }, [open]);

  // ===================================================
  // SHARED SAVE (footer)
  // ===================================================
  const [saving, setSaving] = React.useState(false);

  React.useEffect(() => {
    if (!open) setSaving(false);
  }, [open]);

  const handleSave = React.useCallback(async () => {
    if (saving) return;

    setSaving(true);
    try {
      await Promise.resolve(onSave());
      toast.success("Saved.");
    } catch (e: unknown) {
      console.error("[WageModal] Save failed", e);
      const msg = e instanceof Error ? e.message : "Failed to save.";
      toast.error(msg);
    } finally {
      setSaving(false);
    }
  }, [onSave, saving]);

  // ===================================================
  // LOANS (CRUD) + COOP support
  // ===================================================
  const [loanPanelOpen, setLoanPanelOpen] = React.useState(false);
  const [loanSaving, setLoanSaving] = React.useState(false);
  const [loanLoading, setLoanLoading] = React.useState(false);
  const [loans, setLoans] = React.useState<EmployeeLoanRecord[]>([]);
  const [editingLoanId, setEditingLoanId] = React.useState<number | null>(null);

  const defaultLoanDraft = React.useCallback((): LoanDraft => {
    const today = toLocalYmd(new Date());
    return {
      loan_amount: "0.00",
      loan_type: "VALE",
      months_to_pay: "1",
      start_date: today,
      end_date: "",
      monthly_payment: "0.00",
      interest_rate: "0.00",
      interest_amount: "0.00",
      net_amount_released: "0.00",
      accumulated_amount: "0.00",
      status: "ACTIVE",
    };
  }, []);

  const [loanDraft, setLoanDraft] = React.useState<LoanDraft>(defaultLoanDraft);

  const resetLoanDraft = React.useCallback(() => {
    setLoanDraft(defaultLoanDraft());
    setEditingLoanId(null);
  }, [defaultLoanDraft]);

  const recomputeLoanDraft = React.useCallback(
    (draft: LoanDraft): LoanDraft => {
      const amt = Number(draft.loan_amount);
      const monthly_payment = computeMonthlyPayment(
        draft.loan_amount,
        draft.months_to_pay,
      );

      if (draft.loan_type === "COOP") {
        const coop = computeCoopInterest(amt);
        return {
          ...draft,
          monthly_payment,
          interest_rate: coop.interestRate,
          interest_amount: coop.interestAmount,
          net_amount_released: coop.netAmountReleased,
        };
      }

      return {
        ...draft,
        monthly_payment,
        interest_rate: "0.00",
        interest_amount: "0.00",
        net_amount_released: "0.00",
      };
    },
    [],
  );

  const loadLoans = React.useCallback(async () => {
    if (!selectedEmployee) return;
    setLoanLoading(true);
    try {
      const rows = await wageApi.fetchEmployeeLoansByUser(
        selectedEmployee.user_id,
      );
      setLoans(rows);
    } catch (e: unknown) {
      console.error("[WageModal] Failed to load loans", e);
      const msg = e instanceof Error ? e.message : "Failed to load employee loans.";
      toast.error(msg);
    } finally {
      setLoanLoading(false);
    }
  }, [selectedEmployee]);

  const validateLoanDraft = React.useCallback(() => {
    const loanAmount = Number(loanDraft.loan_amount);
    const monthsToPay = Number(loanDraft.months_to_pay);

    if (!Number.isFinite(loanAmount) || loanAmount <= 0) {
      toast.error("Loan amount must be greater than 0.");
      return null;
    }
    if (!Number.isInteger(monthsToPay) || monthsToPay <= 0) {
      toast.error("Months to pay must be a positive whole number.");
      return null;
    }

    if (loanDraft.loan_type === "COOP") {
      if (!loanDraft.start_date || !isYmd(loanDraft.start_date)) {
        toast.error("Start date is required for COOP loans.");
        return null;
      }
    }

    const monthlyPayment = round2(loanAmount / monthsToPay);
    if (!Number.isFinite(monthlyPayment) || monthlyPayment <= 0) {
      toast.error("Monthly payment must be greater than 0.");
      return null;
    }

    return { loanAmount, monthsToPay, monthlyPayment };
  }, [loanDraft]);

  const saveLoan = React.useCallback(async () => {
    if (!selectedEmployee) return;

    const v = validateLoanDraft();
    if (!v) return;

    const loggedUserId = getLoggedUserId();
    if (!loggedUserId) {
      toast.error("User session missing.");
      return;
    }

    const coop = loanDraft.loan_type === "COOP";
    const start_date = coop
      ? loanDraft.start_date
      : isYmd(loanDraft.start_date)
        ? loanDraft.start_date
        : toLocalYmd(new Date());

    const loan_amount = round2(v.loanAmount);
    const months_to_pay = v.monthsToPay;
    const monthly_payment = round2(v.monthlyPayment);

    const interest_rate = coop ? 3 : 0;
    const interest_amount = coop ? round2(v.loanAmount * 0.03) : 0;
    const net_amount_released = coop
      ? round2(v.loanAmount - interest_amount)
      : 0;

    setLoanSaving(true);
    try {
      if (editingLoanId) {
        await wageApi.patchEmployeeLoan(editingLoanId, {
          loan_type: loanDraft.loan_type,
          loan_amount,
          months_to_pay,
          monthly_payment,
          start_date,
          interest_rate,
          interest_amount,
          net_amount_released,
          updated_by: loggedUserId,
        });
        toast.success("Loan updated.");
      } else {
        await wageApi.createEmployeeLoan({
          user_id: selectedEmployee.user_id,
          loan_type: loanDraft.loan_type,
          loan_amount,
          months_to_pay,
          monthly_payment,
          start_date,
          end_date: null,
          interest_rate,
          interest_amount,
          net_amount_released,
          accumulated_amount: 0,
          status: "ACTIVE",
          created_by: loggedUserId,
          updated_by: loggedUserId,
        });
        toast.success("Loan added.");
      }

      resetLoanDraft();
      setLoanPanelOpen(false);
      await loadLoans();
    } catch (e: unknown) {
      console.error("[WageModal] Loan save failed", e);
      const msg = e instanceof Error ? e.message : "Failed to save loan.";
      toast.error(msg);
    } finally {
      setLoanSaving(false);
    }
  }, [
    editingLoanId,
    loanDraft.loan_type,
    loanDraft.start_date,
    loadLoans,
    resetLoanDraft,
    selectedEmployee,
    validateLoanDraft,
  ]);

  const startEditLoan = React.useCallback(
    (l: EmployeeLoanRecord) => {
      setEditingLoanId(l.loan_id);
      setLoanPanelOpen(true);

      const loan_amount = money(l.loan_amount);
      const months_to_pay = String(l.months_to_pay ?? 1);
      const start_date =
        (l.start_date || "").substring(0, 10) || toLocalYmd(new Date());

      const base: LoanDraft = {
        loan_type: l.loan_type,
        loan_amount,
        months_to_pay,
        start_date,
        end_date: (l.end_date || "").substring(0, 10),
        monthly_payment: computeMonthlyPayment(loan_amount, months_to_pay),
        interest_rate: money(l.interest_rate ?? 0),
        interest_amount: money(l.interest_amount ?? 0),
        net_amount_released: money(l.net_amount_released ?? 0),
        accumulated_amount: money(l.accumulated_amount ?? 0),
        status: String(l.status ?? "ACTIVE"),
      };

      setLoanDraft(recomputeLoanDraft(base));
    },
    [recomputeLoanDraft],
  );

  const deleteLoan = React.useCallback(
    async (loanId: number) => {
      const loggedUserId = getLoggedUserId();
      if (!loggedUserId) {
        toast.error("User session missing.");
        return;
      }

      if (!window.confirm("Delete this loan? This action cannot be undone."))
        return;

      setLoanSaving(true);
      try {
        await wageApi.deleteEmployeeLoan(loanId);
        toast.success("Loan deleted.");

        if (editingLoanId === loanId) {
          resetLoanDraft();
          setLoanPanelOpen(false);
        }

        await loadLoans();
    } catch (e: unknown) {
      console.error("[WageModal] Delete failed; trying cancel fallback", e);

        try {
          await wageApi.patchEmployeeLoan(loanId, {
            status: "CANCELLED",
            updated_by: loggedUserId,
          });
          toast.success("Loan cancelled (delete not permitted).");

          if (editingLoanId === loanId) {
            resetLoanDraft();
            setLoanPanelOpen(false);
          }

          await loadLoans();
        } catch (e2: unknown) {
          console.error("[WageModal] Cancel fallback failed", e2);
          const msg1 = e instanceof Error ? e.message : "Failed to delete/cancel loan.";
          const msg2 = e2 instanceof Error ? e2.message : msg1;
          toast.error(msg2);
        }
      } finally {
        setLoanSaving(false);
      }
    },
    [editingLoanId, loadLoans, resetLoanDraft],
  );

  // ===================================================
  // RETRO PAY (CRUD) + CUTOFF selection
  // ===================================================
  const [retroLoading, setRetroLoading] = React.useState(false);
  const [retroSaving, setRetroSaving] = React.useState(false);
  const [retroRows, setRetroRows] = React.useState<RetroPayRecord[]>([]);
  const [retroFormOpen, setRetroFormOpen] = React.useState(false);
  const [editingRetroId, setEditingRetroId] = React.useState<number | null>(
    null,
  );

  const [cutoffsLoading, setCutoffsLoading] = React.useState(false);
  const [cutoffs, setCutoffs] = React.useState<CutoffSetting[]>([]);

  const defaultRetroDraft = React.useCallback((): RetroPayDraft => {
    return {
      amount: "0.00",
      description: "",
      cutoff_setting_id: null,
      cutoff_start: "",
      cutoff_end: "",
      is_processed: 0,
    };
  }, []);

  const [retroDraft, setRetroDraft] =
    React.useState<RetroPayDraft>(defaultRetroDraft);

  const resetRetroDraft = React.useCallback(() => {
    setRetroDraft(defaultRetroDraft());
    setEditingRetroId(null);
  }, [defaultRetroDraft]);

  const loadCutoffSettings = React.useCallback(async () => {
    setCutoffsLoading(true);
    try {
      const rows = await wageApi.fetchCutoffSettingsOpen();
      setCutoffs(rows);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : "Failed to load cutoff settings.";
      console.error("[WageModal] Failed to load cutoff settings", e);
      toast.error(msg);
      setCutoffs([]);
    } finally {
      setCutoffsLoading(false);
    }
  }, []);

  const applyCutoffSelection = React.useCallback(
    (cutoffId: number | null) => {
      if (!cutoffId) {
        setRetroDraft((p) => ({
          ...p,
          cutoff_setting_id: null,
          cutoff_start: "",
          cutoff_end: "",
        }));
        return;
      }

      const c = cutoffs.find((x) => x.id === cutoffId);
      if (!c) {
        setRetroDraft((p) => ({
          ...p,
          cutoff_setting_id: null,
          cutoff_start: "",
          cutoff_end: "",
        }));
        return;
      }

      setRetroDraft((p) => ({
        ...p,
        cutoff_setting_id: cutoffId,
        cutoff_start: c.start_date,
        cutoff_end: c.end_date,
      }));
    },
    [cutoffs],
  );

  const loadRetroPay = React.useCallback(async () => {
    if (!selectedEmployee) return;
    setRetroLoading(true);
    try {
      const rows = await wageApi.fetchRetroPayByUser(selectedEmployee.user_id);
      setRetroRows(rows);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : "Failed to load retro pay.";
      console.error("[WageModal] Failed to load retro pay", e);
      toast.error(msg);
    } finally {
      setRetroLoading(false);
    }
  }, [selectedEmployee]);

  const validateRetroDraft = React.useCallback(() => {
    const amt = Number(retroDraft.amount);
    if (!Number.isFinite(amt) || amt <= 0) {
      toast.error("Retro pay amount must be greater than 0.");
      return null;
    }

    if (!retroDraft.cutoff_setting_id) {
      toast.error("Please select a cutoff period (1st or 2nd).");
      return null;
    }

    if (!isYmd(retroDraft.cutoff_start) || !isYmd(retroDraft.cutoff_end)) {
      toast.error("Selected cutoff period is invalid.");
      return null;
    }

    if (retroDraft.cutoff_start > retroDraft.cutoff_end) {
      toast.error("Selected cutoff period is invalid.");
      return null;
    }

    return { amt: round2(amt) };
  }, [retroDraft]);

  const saveRetro = React.useCallback(async () => {
    if (!selectedEmployee) return;

    const loggedUserId = getLoggedUserId();
    if (!loggedUserId) {
      toast.error("User session missing.");
      return;
    }

    const v = validateRetroDraft();
    if (!v) return;

    setRetroSaving(true);
    try {
      if (editingRetroId) {
        await wageApi.patchRetroPay(editingRetroId, {
          amount: v.amt,
          description: retroDraft.description?.trim() || null,
          cutoff_start: retroDraft.cutoff_start,
          cutoff_end: retroDraft.cutoff_end,
          is_processed: retroDraft.is_processed,
          updated_by: loggedUserId,
        });
        toast.success("Retro pay updated.");
      } else {
        await wageApi.createRetroPay({
          user_id: selectedEmployee.user_id,
          amount: v.amt,
          description: retroDraft.description?.trim() || null,
          cutoff_start: retroDraft.cutoff_start,
          cutoff_end: retroDraft.cutoff_end,
          is_processed: retroDraft.is_processed ?? 0,
          created_by: loggedUserId,
          updated_by: loggedUserId,
        });
        toast.success("Retro pay added.");
      }

      resetRetroDraft();
      setRetroFormOpen(false);
      await loadRetroPay();
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : "Failed to save retro pay.";
      console.error("[WageModal] Retro pay save failed", e);
      toast.error(msg);
    } finally {
      setRetroSaving(false);
    }
  }, [
    editingRetroId,
    loadRetroPay,
    resetRetroDraft,
    retroDraft,
    selectedEmployee,
    validateRetroDraft,
  ]);

  const startEditRetro = React.useCallback(
    (r: RetroPayRecord) => {
      setEditingRetroId(r.retro_id);
      setRetroFormOpen(true);

      const start = (r.cutoff_start || "").substring(0, 10);
      const end = (r.cutoff_end || "").substring(0, 10);

      const matched =
        cutoffs.find((c) => c.start_date === start && c.end_date === end) ||
        null;

      setRetroDraft({
        amount: money(r.amount),
        description: r.description ?? "",
        cutoff_setting_id: matched?.id ?? null,
        cutoff_start: start,
        cutoff_end: end,
        is_processed: Number(r.is_processed) === 1 ? 1 : 0,
      });
    },
    [cutoffs],
  );

  const deleteRetro = React.useCallback(
    async (retroId: number) => {
      const loggedUserId = getLoggedUserId();
      if (!loggedUserId) {
        toast.error("User session missing.");
        return;
      }

      const row = retroRows.find((x) => x.retro_id === retroId);
      if (row && Number(row.is_processed) === 1) {
        toast.error("Processed retro pay entries cannot be deleted.");
        return;
      }

      if (
        !window.confirm(
          "Delete this retro pay entry? This action cannot be undone.",
        )
      )
        return;

      setRetroSaving(true);
      try {
        await wageApi.deleteRetroPay(retroId);
        toast.success("Retro pay deleted.");

        if (editingRetroId === retroId) {
          resetRetroDraft();
          setRetroFormOpen(false);
        }

        await loadRetroPay();
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : "Failed to delete retro pay.";
        console.error("[WageModal] Retro pay delete failed", e);
        toast.error(msg);
      } finally {
        setRetroSaving(false);
      }
    },
    [editingRetroId, loadRetroPay, resetRetroDraft, retroRows],
  );

  // ===================================================
  // OTHER ADDITIONS / DEDUCTIONS (CRUD)
  // ===================================================
  const [addLoading, setAddLoading] = React.useState(false);
  const [addSaving, setAddSaving] = React.useState(false);
  const [addRows, setAddRows] = React.useState<PayrollOtherAdditionRecord[]>(
    [],
  );
  const [addFormOpen, setAddFormOpen] = React.useState(false);
  const [editingAddId, setEditingAddId] = React.useState<number | null>(null);

  const [dedLoading, setDedLoading] = React.useState(false);
  const [dedSaving, setDedSaving] = React.useState(false);
  const [dedRows, setDedRows] = React.useState<PayrollOtherDeductionRecord[]>(
    [],
  );
  const [dedFormOpen, setDedFormOpen] = React.useState(false);
  const [editingDedId, setEditingDedId] = React.useState<number | null>(null);

  const defaultOtherDraft = React.useCallback((): PayrollOtherADDraft => {
    return {
      amount: "0.00",
      description: "",
      cutoff_setting_id: null,
      cutoff_start: "",
      cutoff_end: "",
    };
  }, []);

  const [addDraft, setAddDraft] =
    React.useState<PayrollOtherADDraft>(defaultOtherDraft);
  const [dedDraft, setDedDraft] =
    React.useState<PayrollOtherADDraft>(defaultOtherDraft);

  const resetAddDraft = React.useCallback(() => {
    setAddDraft(defaultOtherDraft());
    setEditingAddId(null);
  }, [defaultOtherDraft]);

  const resetDedDraft = React.useCallback(() => {
    setDedDraft(defaultOtherDraft());
    setEditingDedId(null);
  }, [defaultOtherDraft]);

  const applyCutoffToOtherDraft = React.useCallback(
    (cutoffId: number | null, kind: "add" | "ded") => {
      const setDraft = kind === "add" ? setAddDraft : setDedDraft;

      if (!cutoffId) {
        setDraft((p) => ({
          ...p,
          cutoff_setting_id: null,
          cutoff_start: "",
          cutoff_end: "",
        }));
        return;
      }

      const c = cutoffs.find((x) => x.id === cutoffId);
      if (!c) {
        setDraft((p) => ({
          ...p,
          cutoff_setting_id: null,
          cutoff_start: "",
          cutoff_end: "",
        }));
        return;
      }

      setDraft((p) => ({
        ...p,
        cutoff_setting_id: cutoffId,
        cutoff_start: c.start_date,
        cutoff_end: c.end_date,
      }));
    },
    [cutoffs],
  );

  const validateOtherDraft = React.useCallback((d: PayrollOtherADDraft) => {
    const amt = Number(d.amount);
    if (!Number.isFinite(amt) || amt <= 0) {
      toast.error("Amount must be greater than 0.");
      return null;
    }

    if (!d.cutoff_setting_id) {
      toast.error("Please select a cutoff period.");
      return null;
    }

    if (!isYmd(d.cutoff_start) || !isYmd(d.cutoff_end)) {
      toast.error("Selected cutoff period is invalid.");
      return null;
    }

    if (d.cutoff_start > d.cutoff_end) {
      toast.error("Selected cutoff period is invalid.");
      return null;
    }

    return { amt: round2(amt) };
  }, []);

  const loadOtherAdditions = React.useCallback(async () => {
    if (!selectedEmployee) return;
    setAddLoading(true);
    try {
      const rows = await wageApi.fetchPayrollOtherAdditionsByUser(
        selectedEmployee.user_id,
      );
      setAddRows(rows);
    } catch (e: unknown) {
      console.error("[WageModal] Failed to load other additions", e);
      const msg = e instanceof Error ? e.message : "Failed to load other additions.";
      toast.error(msg);
    } finally {
      setAddLoading(false);
    }
  }, [selectedEmployee]);

  const loadOtherDeductions = React.useCallback(async () => {
    if (!selectedEmployee) return;
    setDedLoading(true);
    try {
      const rows = await wageApi.fetchPayrollOtherDeductionsByUser(
        selectedEmployee.user_id,
      );
      setDedRows(rows);
    } catch (e: unknown) {
      console.error("[WageModal] Failed to load other deductions", e);
      const msg = e instanceof Error ? e.message : "Failed to load other deductions.";
      toast.error(msg);
    } finally {
      setDedLoading(false);
    }
  }, [selectedEmployee]);

  const saveOtherAddition = React.useCallback(async () => {
    if (!selectedEmployee) return;

    const loggedUserId = getLoggedUserId();
    if (!loggedUserId) {
      toast.error("User session missing.");
      return;
    }

    const v = validateOtherDraft(addDraft);
    if (!v) return;

    setAddSaving(true);
    try {
      if (editingAddId) {
        await wageApi.patchPayrollOtherAddition(editingAddId, {
          amount: v.amt,
          description: addDraft.description?.trim() || null,
          cutoff_start: addDraft.cutoff_start,
          cutoff_end: addDraft.cutoff_end,
        });
        toast.success("Other addition updated.");
      } else {
        await wageApi.createPayrollOtherAddition({
          user_id: selectedEmployee.user_id,
          amount: v.amt,
          description: addDraft.description?.trim() || null,
          cutoff_start: addDraft.cutoff_start,
          cutoff_end: addDraft.cutoff_end,
          created_by: loggedUserId,
        });
        toast.success("Other addition added.");
      }

      resetAddDraft();
      setAddFormOpen(false);
      await loadOtherAdditions();
    } catch (e: unknown) {
      console.error("[WageModal] Save other addition failed", e);
      const msg = e instanceof Error ? e.message : "Failed to save other addition.";
      toast.error(msg);
    } finally {
      setAddSaving(false);
    }
  }, [
    addDraft,
    editingAddId,
    loadOtherAdditions,
    resetAddDraft,
    selectedEmployee,
    validateOtherDraft,
  ]);

  const saveOtherDeduction = React.useCallback(async () => {
    if (!selectedEmployee) return;

    const loggedUserId = getLoggedUserId();
    if (!loggedUserId) {
      toast.error("User session missing.");
      return;
    }

    const v = validateOtherDraft(dedDraft);
    if (!v) return;

    setDedSaving(true);
    try {
      if (editingDedId) {
        await wageApi.patchPayrollOtherDeduction(editingDedId, {
          amount: v.amt,
          description: dedDraft.description?.trim() || null,
          cutoff_start: dedDraft.cutoff_start,
          cutoff_end: dedDraft.cutoff_end,
        });
        toast.success("Other deduction updated.");
      } else {
        await wageApi.createPayrollOtherDeduction({
          user_id: selectedEmployee.user_id,
          amount: v.amt,
          description: dedDraft.description?.trim() || null,
          cutoff_start: dedDraft.cutoff_start,
          cutoff_end: dedDraft.cutoff_end,
          created_by: loggedUserId,
        });
        toast.success("Other deduction added.");
      }

      resetDedDraft();
      setDedFormOpen(false);
      await loadOtherDeductions();
    } catch (e: unknown) {
      console.error("[WageModal] Save other deduction failed", e);
      const msg = e instanceof Error ? e.message : "Failed to save other deduction.";
      toast.error(msg);
    } finally {
      setDedSaving(false);
    }
  }, [
    dedDraft,
    editingDedId,
    loadOtherDeductions,
    resetDedDraft,
    selectedEmployee,
    validateOtherDraft,
  ]);

  const startEditOtherAddition = React.useCallback(
    (r: PayrollOtherAdditionRecord) => {
      setEditingAddId(r.id);
      setAddFormOpen(true);

      const start = (r.cutoff_start || "").substring(0, 10);
      const end = (r.cutoff_end || "").substring(0, 10);
      const matched =
        cutoffs.find((c) => c.start_date === start && c.end_date === end) ||
        null;

      setAddDraft({
        amount: money(r.amount),
        description: r.description ?? "",
        cutoff_setting_id: matched?.id ?? null,
        cutoff_start: start,
        cutoff_end: end,
      });
    },
    [cutoffs],
  );

  const startEditOtherDeduction = React.useCallback(
    (r: PayrollOtherDeductionRecord) => {
      setEditingDedId(r.id);
      setDedFormOpen(true);

      const start = (r.cutoff_start || "").substring(0, 10);
      const end = (r.cutoff_end || "").substring(0, 10);
      const matched =
        cutoffs.find((c) => c.start_date === start && c.end_date === end) ||
        null;

      setDedDraft({
        amount: money(r.amount),
        description: r.description ?? "",
        cutoff_setting_id: matched?.id ?? null,
        cutoff_start: start,
        cutoff_end: end,
      });
    },
    [cutoffs],
  );

  const deleteOtherAddition = React.useCallback(
    async (id: number) => {
      if (
        !window.confirm("Delete this addition? This action cannot be undone.")
      )
        return;

      setAddSaving(true);
      try {
        await wageApi.deletePayrollOtherAddition(id);
        toast.success("Other addition deleted.");

        if (editingAddId === id) {
          resetAddDraft();
          setAddFormOpen(false);
        }

        await loadOtherAdditions();
      } catch (e: unknown) {
        console.error("[WageModal] Delete other addition failed", e);
        const msg = e instanceof Error ? e.message : "Failed to delete other addition.";
        toast.error(msg);
      } finally {
        setAddSaving(false);
      }
    },
    [editingAddId, loadOtherAdditions, resetAddDraft],
  );

  const deleteOtherDeduction = React.useCallback(
    async (id: number) => {
      if (
        !window.confirm("Delete this deduction? This action cannot be undone.")
      )
        return;

      setDedSaving(true);
      try {
        await wageApi.deletePayrollOtherDeduction(id);
        toast.success("Other deduction deleted.");

        if (editingDedId === id) {
          resetDedDraft();
          setDedFormOpen(false);
        }

        await loadOtherDeductions();
      } catch (e: unknown) {
        console.error("[WageModal] Delete other deduction failed", e);
        const msg = e instanceof Error ? e.message : "Failed to delete other deduction.";
        toast.error(msg);
      } finally {
        setDedSaving(false);
      }
    },
    [editingDedId, loadOtherDeductions, resetDedDraft],
  );

  // ===================================================
  // Modal open/close lifecycle
  // ===================================================
  React.useEffect(() => {
    if (!open) {
      setLoanPanelOpen(false);
      resetLoanDraft();
      setLoans([]);

      setRetroFormOpen(false);
      resetRetroDraft();
      setRetroRows([]);

      setAddFormOpen(false);
      resetAddDraft();
      setAddRows([]);

      setDedFormOpen(false);
      resetDedDraft();
      setDedRows([]);

      setCutoffs([]);
      return;
    }

    if (!selectedEmployee) return;

    void loadLoans();
    void loadRetroPay();
    void loadCutoffSettings();
    void loadOtherAdditions();
    void loadOtherDeductions();
  }, [
    open,
    selectedEmployee,
    loadLoans,
    loadRetroPay,
    loadCutoffSettings,
    loadOtherAdditions,
    loadOtherDeductions,
    resetLoanDraft,
    resetRetroDraft,
    resetAddDraft,
    resetDedDraft,
  ]);

  const employeeLabel = selectedEmployee
    ? `${selectedEmployee.user_fname} ${selectedEmployee.user_lname}`
    : "Unknown Employee";

  const summary = React.useMemo(() => {
    const num = (v: string | number | null | undefined) => {
      const n = Number(String(v ?? "0").replace(/,/g, ""));
      return Number.isFinite(n) ? n : 0;
    };

    const daily = num(wageData.dailyWage || wageData.dailyWageInput || 0);

    const sss = num(wageData.sss);
    const pagibig = num(wageData.pagibig);
    const philhealth = num(wageData.philhealth);

    const contribTotal = sss + pagibig + philhealth;

    const activeLoans = loans.filter(
      (l) => String(l.status || "").toUpperCase() === "ACTIVE",
    ).length;

    const pendingRetro = retroRows.filter(
      (r) => Number(r.is_processed) !== 1,
    ).length;

    const addTotal = addRows.reduce((sum, r) => sum + num(r.amount), 0);
    const dedTotal = dedRows.reduce((sum, r) => sum + num(r.amount), 0);

    return {
      daily,
      contribTotal,
      activeLoans,
      pendingRetro,
      addTotal,
      dedTotal,
    };
  }, [wageData, loans, retroRows, addRows, dedRows]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        aria-describedby={undefined}
        // ✅ Fix: hide the shadcn default close button (prevents double X / overlap)
        className={`${MODAL_WIDTH} w-full p-0 overflow-hidden rounded-xl border shadow-2xl [&>button]:hidden`}
      >
        <div className="flex max-h-[85vh] flex-col">
          {/* Header */}
          <div className="relative shrink-0 border-b bg-white dark:bg-slate-950">
            <div className="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-persian-blue-700 via-indigo-600 to-cyan-500" />

            <div className="px-6 pt-5 pb-4">
              <div className="flex items-start justify-between gap-4">
                <div className="min-w-0">
                  <DialogHeader>
                    <DialogTitle className="text-xl sm:text-2xl font-semibold text-slate-900 dark:text-slate-50">
                      Employee Compensation
                    </DialogTitle>
                  </DialogHeader>

                  <div className="mt-1 flex flex-wrap items-center gap-2 text-sm text-slate-600 dark:text-slate-300">
                    <span className="font-medium text-slate-800 dark:text-slate-100">
                      {employeeLabel}
                    </span>
                    <span className="text-slate-400">•</span>
                    <span className="truncate">
                      Employee ID:{" "}
                      <span className="font-medium text-slate-800 dark:text-slate-100">
                        {selectedEmployee?.user_id ?? "—"}
                      </span>
                    </span>
                  </div>

                  <div className="mt-3 flex flex-wrap items-center gap-2">
                    <Badge
                      variant="secondary"
                      className="bg-slate-100 text-slate-800 hover:bg-slate-100 dark:bg-slate-800 dark:text-slate-100 dark:hover:bg-slate-800"
                    >
                      Daily: ₱ {money(summary.daily)}
                    </Badge>

                    <Badge
                      variant="secondary"
                      className="bg-slate-100 text-slate-800 hover:bg-slate-100 dark:bg-slate-800 dark:text-slate-100 dark:hover:bg-slate-800"
                    >
                      Contributions: ₱ {money(summary.contribTotal)}
                    </Badge>

                    <Badge
                      variant="secondary"
                      className="bg-slate-100 text-slate-800 hover:bg-slate-100 dark:bg-slate-800 dark:text-slate-100 dark:hover:bg-slate-800"
                    >
                      Active Loans: {summary.activeLoans}
                    </Badge>

                    <Badge
                      variant="secondary"
                      className="bg-slate-100 text-slate-800 hover:bg-slate-100 dark:bg-slate-800 dark:text-slate-100 dark:hover:bg-slate-800"
                    >
                      Retro Pending: {summary.pendingRetro}
                    </Badge>

                    {saving && (
                      <Badge className="bg-persian-blue-800 text-white hover:bg-persian-blue-800">
                        Saving…
                      </Badge>
                    )}
                  </div>
                </div>

                <Button
                  type="button"
                  variant="ghost"
                  className="h-9 w-9 rounded-lg"
                  onClick={() => onOpenChange(false)}
                  disabled={saving}
                  title="Close"
                >
                  <X className="h-5 w-5" />
                </Button>
              </div>

              <div className="mt-3 flex flex-wrap items-center gap-3 text-xs text-slate-500 dark:text-slate-400">
                <span>
                  Other Additions:{" "}
                  <span className="font-medium text-slate-700 dark:text-slate-200">
                    ₱ {money(summary.addTotal)}
                  </span>
                </span>
                <span className="text-slate-300 dark:text-slate-700">|</span>
                <span>
                  Other Deductions:{" "}
                  <span className="font-medium text-slate-700 dark:text-slate-200">
                    ₱ {money(summary.dedTotal)}
                  </span>
                </span>
              </div>
            </div>
          </div>

          {/* Body */}
          <div className="flex-1 overflow-y-auto bg-slate-50/60 dark:bg-slate-950">
            <div className="p-6">
              <Tabs
                value={tab}
                onValueChange={(v) => setTab(v as TabKey)}
                className="w-full"
              >
                {/* ✅ Fix: use minmax(0,1fr) so the right pane can shrink without forcing overflow */}
                <div className="grid gap-6 md:grid-cols-[240px_minmax(0,1fr)] md:items-start">
                  {/* Left navigation */}
                  <div className="self-start md:sticky md:top-6">
                    <div className="rounded-xl border bg-white p-2 shadow-sm dark:bg-slate-950">
                      {/* ✅ Fix: force TabsList to h-auto to avoid overlaps/messy layout */}
                      <TabsList
                        className="
                          flex h-auto w-full flex-row items-center justify-start gap-2 overflow-x-auto
                          bg-transparent p-0
                          md:flex-col md:items-stretch md:justify-start md:gap-1 md:overflow-visible
                        "
                      >
                        <TabsTrigger
                          value="wage"
                          className="group w-full justify-start gap-3 rounded-lg px-3 py-2.5 text-left
                            text-slate-700 dark:text-slate-200
                            data-[state=active]:bg-persian-blue-800 data-[state=active]:text-white
                            data-[state=active]:shadow-sm"
                        >
                          <Wallet className="h-4 w-4 opacity-80 group-data-[state=active]:opacity-100" />
                          <span className="hidden md:flex md:flex-col md:leading-tight">
                            <span className="text-sm font-medium">Wage</span>
                            <span className="text-xs font-normal text-slate-500 group-data-[state=active]:text-white/80">
                              Daily wage, leaves, flags
                            </span>
                          </span>
                          <span className="md:hidden text-sm font-medium">
                            Wage
                          </span>
                        </TabsTrigger>

                        {/* ✅ Savings (now consistent) */}
                        <TabsTrigger
                          value="savings"
                          className="group w-full justify-start gap-3 rounded-lg px-3 py-2.5 text-left
                            text-slate-700 dark:text-slate-200
                            data-[state=active]:bg-persian-blue-800 data-[state=active]:text-white
                            data-[state=active]:shadow-sm"
                        >
                          <PiggyBank className="h-4 w-4 opacity-80 group-data-[state=active]:opacity-100" />
                          <span className="hidden md:flex md:flex-col md:leading-tight">
                            <span className="text-sm font-medium">Savings</span>
                            <span className="text-xs font-normal text-slate-500 group-data-[state=active]:text-white/80">
                              COOP savings / membership
                            </span>
                          </span>
                          <span className="md:hidden text-sm font-medium">
                            Savings
                          </span>
                        </TabsTrigger>

